const itemJson = $input.item.json || {};
const input = itemJson.body || itemJson.payload || itemJson;
const authUser = itemJson.user || {};
const userRole = String(authUser.role || 'admin').toLowerCase().trim();

if (userRole !== 'admin') {
  return {
    json: {
      valid: false,
      errorMessage: 'Acesso negado: apenas administradores podem gerenciar usuários.'
    }
  };
}

const id = input.id ? Number(input.id) : null;
const isUpdate = Boolean(id);
const currentUserId = Number(authUser.user_id || authUser.id || 0);

const nome = String(input.nome || '').trim();
const email = String(input.email || '').trim().toLowerCase();
const whatsapp = String(input.whatsapp || '').replace(/\D/g, '');
const password = String(input.password || '');
const role = String(input.role || 'operador').toLowerCase().trim() === 'admin' ? 'admin' : 'operador';
const ativo = input.ativo !== undefined ? Boolean(input.ativo) : true;

if (!nome) {
  return { json: { valid: false, errorMessage: 'O nome do usuário é obrigatório.' } };
}

if (!email || !email.includes('@')) {
  return { json: { valid: false, errorMessage: 'Informe um endereço de e-mail válido.' } };
}

if (!whatsapp || whatsapp.length < 10) {
  return { json: { valid: false, errorMessage: 'Informe um número de WhatsApp válido com DDD.' } };
}

if (!isUpdate && password.length < 6) {
  return { json: { valid: false, errorMessage: 'A senha inicial deve ter pelo menos 6 caracteres.' } };
}

if (isUpdate && password.length > 0 && password.length < 6) {
  return { json: { valid: false, errorMessage: 'A nova senha deve ter pelo menos 6 caracteres.' } };
}

if (isUpdate && currentUserId && id === currentUserId && (!ativo || role !== 'admin')) {
  return {
    json: {
      valid: false,
      errorMessage: 'Por segurança, você não pode desativar ou remover privilégios de administrador da sua própria conta.'
    }
  };
}

return {
  json: {
    valid: true,
    id,
    isUpdate,
    nome,
    email,
    whatsapp,
    password,
    role,
    ativo
  }
};

return {
  json: {
    ok: false,
    message: $input.item.json.errorMessage || 'Dados inválidos.'
  }
};

const dup = $input.item.json || {};
const prep = $('Preparar e Validar Dados').first().json;

if (dup && dup.id) {
  const sameEmail = String(dup.email || '').toLowerCase() === prep.email;
  return {
    json: {
      hasDuplicate: true,
      duplicateMessage: sameEmail
        ? 'Já existe outro usuário cadastrado com este e-mail.'
        : 'Já existe outro usuário cadastrado com este número de WhatsApp.'
    }
  };
}

return {
  json: {
    hasDuplicate: false,
    ...prep
  }
};

return {
  json: {
    ok: false,
    message: $input.item.json.duplicateMessage || 'Já existe outro usuário com este e-mail ou WhatsApp.'
  }
};

